function sellItem(name){if(!state.items[name])return;let c=cropData.find(x=>x.name===name);setItem(name,-1);state.money+=c?.value||18;showToast(`${name} sold for ◈ ${c?.value||18}.`);render()}
function renderTab(){document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===state.tab));let root=document.getElementById('tabContent');if(state.tab==='bag'){let names=Object.keys(state.items);root.innerHTML=names.length?`<div class="inventory-list">${names.map(n=>`<div class="inv-row"><span class="inv-emoji">${cropData.find(c=>c.name===n)?.emoji||'📦'}</span><div class="inv-info"><strong>${n}</strong><small>${(state.itemTimes[n]&&Date.now()-state.itemTimes[n]>90000)?'getting a little soft':'freshly gathered'}</small></div><span class="inv-qty">× ${state.items[n]}</span></div>`).join('')}</div><p class="hint">Fresh harvest keeps for 90 seconds, then becomes waste. Stage it in a latch store to keep it safe.</p>`:'<div class="empty-note">Your pockets are peacefully empty. Harvest a crop to begin.</div>';}
else if(state.tab==='livestock'){let cow=cowAdjs[state.animals.cow%16],hen=henAdjs[state.animals.hen%32];root.innerHTML=`<div class="animals"><div class="animal"><div class="animal-line"><b>🐄 ${state.animals.cow?cow+' cow':'No cow yet'}</b><span>×${state.animals.cow}</span></div><small>${state.animals.cow?'Full-fat milk specialist':'A gentle milk maker'}</small><button data-animal="cow" ${state.money<85?'disabled':''}>${state.animals.cow?'ADOPT ANOTHER · ◈85':'ADOPT · ◈85'}</button></div><div class="animal"><div class="animal-line"><b>🐔 ${hen} hen</b><span>×${state.animals.hen}</span></div><small>Small egg specialist · lays every so often</small><button id="collectEgg">COLLECT EGG ${state.items.Egg?`· ×${state.items.Egg}`:''}</button></div></div><p class="hint">Feed critters with plot trash or pocket food. Each type brings its own specialty—there is no best one.</p>`;root.querySelector('[data-animal]')?.addEventListener('click',()=>{if(state.money<85)return;state.money-=85;state.animals.cow++;showToast('A new gentle cow has found a home.');render()});root.querySelector('#collectEgg').onclick=()=>{setItem('Egg',1);state.itemTimes.Egg=Date.now();showToast(`${hen} left a little egg.`);render()}}
else{root.innerHTML=`<div class="inventory-list"><div class="inv-row"><span class="inv-emoji">🌾</span><div class="inv-info"><strong>Seeds</strong><small>${Object.values(state.seeds).reduce((a,b)=>a+b,0)} seeds · ${crops.length} varieties</small></div><span class="inv-qty">40</span></div><div class="inv-row"><span class="inv-emoji">🐄</span><div class="inv-info"><strong>Cow neighbors</strong><small>${state.animals.cow} of 16 cozy varieties</small></div><span class="inv-qty">16</span></div><div class="inv-row"><span class="inv-emoji">🐔</span><div class="inv-info"><strong>Chicken neighbors</strong><small>${state.animals.hen} of 32 tiny varieties</small></div><span class="inv-qty">32</span></div><div class="inv-row"><span class="inv-emoji">🪨</span><div class="inv-info"><strong>Coal strains</strong><small>Static seed #${String(state.coal+1).padStart(2,'0')} · ${coalNames[state.coal%64]}</small></div><span class="inv-qty">64</span></div></div><p class="hint">Every crop has its own sell value and growth rhythm. Mutations stay a surprise until harvest. Your coal seed never changes.</p><button class="action-btn" style="width:100%;margin-top:10px" id="openSeedMarket">BROWSE THE SEED LIBRARY ↗</button>`;root.querySelector('#openSeedMarket').onclick=openMarket}}
function renderActions(){let p=state.plots[state.selected],root=document.getElementById('plotActions');if(!p)return;let plotName=`Plot ${String(state.selected+1).padStart(2,'0')}`;if(p.building){let title=p.building==='belt'?'Belt':p.building==='store'?'Latch store':'Fertilizer applicator';root.innerHTML=`<div class="selected-card"><div class="selected-title"><strong>${title} · ${plotName}</strong><span>◈ ${p.building==='belt'?8:p.building==='store'?30:40}</span></div><div class="selected-detail">${p.building==='store'?`${p.store||0} / 8 items staged · items here stay fresh.`:'A tiny useful bit of farm machinery.'}</div><div class="action-row"><button class="action-btn" id="clearBuild">CLEAR EQUIPMENT</button>${p.building==='store'?'<button class="action-btn primary" id="stageItems">STAGE HARVEST</button>':''}</div></div>`;root.querySelector('#clearBuild').onclick=()=>{if(p.store){showToast('Empty the latch store before clearing it.');return}p.building=null;showToast('Equipment cleared.');render()};root.querySelector('#stageItems')?.addEventListener('click',()=>{let names=Object.keys(state.items);if(!names.length){showToast('Your pockets are empty.');return}let n=names[0],amount=Math.min(state.items[n],8-p.store);if(!amount){showToast('This latch store is full.');return}setItem(n,-amount);p.store+=amount;p.storeName=n;showToast(`${amount} ${n} staged safely.`);render()});return}
if(p.crop!=null){let crop=cropData[p.crop],r=getReady(p);root.innerHTML=`<div class="selected-card"><div class="selected-title"><strong>${crop.emoji} ${crop.name} · ${plotName}</strong><span>${r?'READY':Math.floor(progress(p)*100)+'%'}</span></div><div class="selected-detail">${r?'A lovely harvest is waiting.':`Growing for ${Math.max(1,Math.ceil(crop.grow*(p.fert?2:1)-(Date.now()-p.planted)/1000))} more seconds.`}${p.fert?'<br>✦ Fertilized · harvest leaves the same soil trash again.':''}</div><div class="action-row"><button class="action-btn primary" id="harvestBtn" ${r?'':'disabled'}>${r?'HARVEST ✨':'GROWING…'}</button><button class="action-btn" id="fertBtn" ${state.money<12?'disabled':''}>FERTILIZE · ◈12</button></div></div><label class="hint">Change crop (replanting resets its growth)</label><select class="seed-select" id="cropSelect">${crops.map((n,i)=>`<option value="${i}" ${p.crop===i?'selected':''}>${emojis[i]} ${n} · ◈${cropData[i].value} · ${cropData[i].grow}s</option>`).join('')}</select><div class="action-row"><button class="action-btn" id="replantBtn">PLANT SELECTED</button><button class="action-btn" id="feedTrash">MAKE SOIL TRASH</button></div><p class="hint">Quality is per plant. Fertilizer doubles time and can mutate at harvest; its soil value nudges future chances. Mutated crop is a surprise.</p>`;root.querySelector('#harvestBtn').onclick=()=>harvest(state.selected);root.querySelector('#fertBtn').onclick=()=>fertilize(state.selected);root.querySelector('#replantBtn').onclick=()=>plant(state.selected,Number(root.querySelector('#cropSelect').value));root.querySelector('#feedTrash').onclick=()=>makeTrash(state.selected);return}
root.innerHTML=`<div class="selected-card"><div class="selected-title"><strong>Quiet soil · ${plotName}</strong><span>READY TO PLANT</span></div><div class="selected-detail">Choose a seed and give your soil a little something to do.</div><select class="seed-select" id="emptyCropSelect">${crops.map((n,i)=>`<option value="${i}" ${i===0?'selected':''}>${emojis[i]} ${n} · ◈${cropData[i].value} · ${cropData[i].grow}s</option>`).join('')}</select><div class="action-row"><button class="action-btn primary" id="plantBtn">PLANT SEED · ◈3</button><button class="action-btn" id="fertEmpty" ${state.money<12?'disabled':''}>ADD FERTILIZER</button></div><p class="hint">Tap the fertilizer first to apply it to this plot. A given plot always makes the same trash.</p></div>`;root.querySelector('#plantBtn').onclick=()=>plant(state.selected,Number(root.querySelector('#emptyCropSelect').value));root.querySelector('#fertEmpty').onclick=()=>fertilize(state.selected)}
function renderBuild(){let choices=[['belt','↗','Belt',8],['store','▣','Latch store',30],['applicator','◉','Applicator',40]];document.getElementById('buildGrid').innerHTML=choices.map(([id,icon,label,cost])=>`<button class="build-btn ${state.buildMode===id?'active':''}" data-build="${id}"><span>${icon}</span><div>${label}<small>◈ ${cost}</small></div></button>`).join('');document.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>{state.buildMode=state.buildMode===b.dataset.build?null:b.dataset.build;document.getElementById('modeLabel').textContent=state.buildMode?'PLACE '+state.buildMode.toUpperCase():'TAP A PLOT TO TEND';showToast(state.buildMode?'Tap an empty plot to place it.':'Build mode closed.');render()})}

