function renderOrder(){ensureOrder();let o=state.order;let have=itemCount(o.item);let card=document.getElementById('orderCard');card.innerHTML=`<div class="order-top"><div class="order-name">${cropData.find(c=>c.name===o.item)?.emoji||'📦'} ${o.qty} ${o.item}</div><span class="timer">whenever you're ready</span></div><div class="order-desc">A neighbor on the far side of the rings is looking for a little harvest.</div><div class="order-foot"><span class="reward">◈ ${money(o.reward)}</span><button class="small-btn" id="fillOrder" ${have<o.qty?'disabled':''}>${have<o.qty?'SEND ORDER':'NEED '+(o.qty-have)+' MORE'}</button></div>`;document.getElementById('fillOrder').onclick=()=>{if(itemCount(o.item)>=o.qty){consumeBase(o.item,o.qty);state.money+=o.reward;state.order=null;ensureOrder();showToast('Order delivered. Thank you, little farmer!');render()}}}
function renderMarketPreview(){let names=Object.keys(state.items).slice(0,3);if(!names.length)names=['Glowberry','Moonbean','Starfruit'];document.getElementById('marketPreview').innerHTML=names.map(n=>`<div class="market-row"><span class="item-icon">${cropData.find(c=>n.startsWith(c.name))?.emoji||'📦'}</span><span class="market-name">${n} <span style="color:var(--muted)">×${state.items[n]||0}</span></span><span class="market-price">◈ ${cropData.find(c=>n.startsWith(c.name))?.value||18}</span><button class="sell-btn" data-sell="${n}" ${!state.items[n]?'disabled':''}>SELL 1</button></div>`).join('');document.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>sellItem(b.dataset.sell))}
function sellItem(name){if(!state.items[name])return;let c=cropData.find(x=>name.startsWith(x.name));let price=c?.value||12;setItem(name,-1);state.money+=price;showToast(`${name} sold for ◈ ${price}.`);render()}
function renderTab(){document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===state.tab));let root=document.getElementById('tabContent');if(state.tab==='bag'){let names=Object.keys(state.items);root.innerHTML=names.length?`<div class="inventory-list">${names.map(n=>`<div class="inv-row"><span class="inv-emoji">${cropData.find(c=>n.startsWith(c.name))?.emoji||'📦'}</span><div class="inv-info"><strong>${n}</strong><small>${n.includes('scraps')||n.includes('mulch')||n.includes('husk')?'Plot-made · same every time':'Freshly gathered'}</small></div><span class="inv-qty">× ${state.items[n]}</span>${n.includes('scraps')||n.includes('mulch')||n.includes('husk')?`<button class="sell-btn" data-trash="${n}">COAL</button><button class="sell-btn" data-feed="${n}">FEED</button>`:''}</div>`).join('')}</div><p class="hint">Fresh harvest keeps for 90 seconds, then becomes waste. Stage it in a latch store to keep it safe.</p>`:'<div class="empty-note">Your pockets are peacefully empty. Harvest a crop to begin.</div>';root.querySelectorAll('[data-trash]').forEach(b=>b.onclick=()=>{if(!state.items[b.dataset.trash])return;setItem(b.dataset.trash,-1);state.coal=(state.coal+1)%64;showToast('Scraps converted. Coal seed stays static.');render()});root.querySelectorAll('[data-feed]').forEach(b=>b.onclick=()=>{if(!state.items[b.dataset.feed])return;setItem(b.dataset.feed,-1);state.feed++;showToast('A happy little critter had a snack.');render()});}
else if(state.tab==='livestock'){let cow=cowAdjs[state.animals.cow%16],hen=henAdjs[state.animals.hen%32];root.innerHTML=`<div class="animals"><div class="animal"><div class="animal-line"><b>🐄 ${state.animals.cow?cow+' cow':'No cow yet'}</b><span>×${state.animals.cow}</span></div><small>${state.animals.cow?'Full-fat milk specialist':'A gentle milk maker'}</small><button data-animal="cow" ${state.money<85?'disabled':''}>${state.animals.cow?'ADOPT ANOTHER · ◈85':'ADOPT · ◈85'}</button></div><div class="animal"><div class="animal-line"><b>🐔 ${hen} hen</b><span>×${state.animals.hen}</span></div><small>Small egg specialist · lays every so often</small><button id="collectEgg">COLLECT EGG ${state.items.Egg?`· ×${state.items.Egg}`:''}</button></div></div><p class="hint">Feed critters with plot trash or pocket food. Each type brings its own specialty—there is no best one.</p>`;root.querySelector('[data-animal]')?.addEventListener('click',()=>{if(state.money<85)return;state.money-=85;state.animals.cow++;showToast('A new gentle cow has found a home.');render()});root.querySelector('#collectEgg').onclick=()=>{setItem('Egg',1);state.itemTimes.Egg=Date.now();showToast(`${hen} left a little egg.`);render()}}
else{root.innerHTML=`<div class="inventory-list"><div class="inv-row"><span class="inv-emoji">🌾</span><div class="inv-info"><strong>Seeds</strong><small>${Object.values(state.seeds).reduce((a,b)=>a+b,0)} seeds · ${crops.length} varieties</small></div><span class="inv-qty">40</span></div><div class="inv-row"><span class="inv-emoji">🐄</span><div class="inv-info"><strong>Cow neighbors</strong><small>${state.animals.cow} of 16 cozy varieties</small></div><span class="inv-qty">16</span></div><div class="inv-row"><span class="inv-emoji">🐔</span><div class="inv-info"><strong>Chicken neighbors</strong><small>${state.animals.hen} of 32 tiny varieties</small></div><span class="inv-qty">32</span></div><div class="inv-row"><span class="inv-emoji">🪨</span><div class="inv-info"><strong>Coal strains</strong><small>Static seed #${String(state.coal+1).padStart(2,'0')} · ${coalNames[state.coal%64]}</small></div><span class="inv-qty">64</span></div></div><p class="hint">Every crop has its own sell value and growth rhythm. Mutations stay a surprise until harvest. Your coal seed never changes.</p><button class="action-btn" style="width:100%;margin-top:10px" id="openSeedMarket">BROWSE THE SEED LIBRARY ↗</button>`;root.querySelector('#openSeedMarket').onclick=openMarket}}
function renderActions(){let p=state.plots[state.selected],root=document.getElementById('plotActions');if(!p)return;let plotName=`Plot ${String(state.selected+1).padStart(2,'0')}`;if(p.building){let title=p.building==='belt'?'Belt':p.building==='store'?'Latch store':'Fertilizer applicator';root.innerHTML=`<div class="selected-card"><div class="selected-title"><strong>${title} · ${plotName}</strong><span>◈ ${p.building==='belt'?8:p.building==='store'?30:40}</span></div><div class="selected-detail">${p.building==='store'?`${p.store||0} / 8 items staged · items here stay fresh.`:'A tiny useful bit of farm machinery.'}</div><div class="action-row"><button class="action-btn" id="clearBuild">CLEAR EQUIPMENT</button>${p.building==='store'?'<button class="action-btn primary" id="stageItems">STAGE HARVEST</button>':''}</div></div>`;root.querySelector('#clearBuild').onclick=()=>{if(p.store){showToast('Empty the latch store before clearing it.');return}p.building=null;showToast('Equipment cleared.');render()};root.querySelector('#stageItems')?.addEventListener('click',()=>stageToStore(state.selected));return}
if(p.crop!=null){let crop=cropData[p.crop],r=getReady(p);root.innerHTML=`<div class="selected-card"><div class="selected-title"><strong>${crop.emoji} ${crop.name} · ${plotName}</strong><span>${r?'READY':Math.floor(progress(p)*100)+'%'}</span></div><div class="selected-detail">${r?'A lovely harvest is waiting.':`Growing for ${Math.max(1,Math.ceil(crop.grow*(p.fert?2:1)-(Date.now()-p.planted)/1000))} more seconds.`}${p.fert?'<br>✦ Fertilized · harvest leaves the same soil trash again.':''}</div><div class="action-row"><button class="action-btn primary" id="harvestBtn" ${r?'':'disabled'}>${r?'HARVEST ✨':'GROWING…'}</button><button class="action-btn" id="fertBtn" ${state.money<12?'disabled':''}>FERTILIZE · ◈12</button></div></div><label class="hint">Change crop (replanting resets its growth)</label><select class="seed-select" id="cropSelect">${crops.map((n,i)=>`<option value="${i}" ${p.crop===i?'selected':''}>${emojis[i]} ${n} · ◈${cropData[i].value} · ${cropData[i].grow}s</option>`).join('')}</select><div class="action-row"><button class="action-btn" id="replantBtn">PLANT SELECTED</button><button class="action-btn" id="feedTrash">MAKE SOIL TRASH</button></div><p class="hint">Quality is per plant. Fertilizer doubles time and can mutate at harvest; its soil value nudges future chances. Mutated crop is a surprise.</p>`;root.querySelector('#harvestBtn').onclick=()=>harvest(state.selected);root.querySelector('#fertBtn').onclick=()=>fertilize(state.selected);root.querySelector('#replantBtn').onclick=()=>plant(state.selected,Number(root.querySelector('#cropSelect').value));root.querySelector('#feedTrash').onclick=()=>makeTrash(state.selected);return}
root.innerHTML=`<div class="selected-card"><div class="selected-title"><strong>Quiet soil · ${plotName}</strong><span>READY TO PLANT</span></div><div class="selected-detail">Choose a seed and give your soil a little something to do.</div><select class="seed-select" id="emptyCropSelect">${crops.map((n,i)=>`<option value="${i}" ${i===0?'selected':''}>${emojis[i]} ${n} · ◈${cropData[i].value} · ${cropData[i].grow}s</option>`).join('')}</select><div class="action-row"><button class="action-btn primary" id="plantBtn">PLANT SEED · ◈3</button><button class="action-btn" id="fertEmpty" ${state.money<12?'disabled':''}>ADD FERTILIZER</button></div><p class="hint">Tap the fertilizer first to apply it to this plot. A given plot always makes the same trash.</p></div>`;root.querySelector('#plantBtn').onclick=()=>plant(state.selected,Number(root.querySelector('#emptyCropSelect').value));root.querySelector('#fertEmpty').onclick=()=>fertilize(state.selected)}
function plant(index,crop){let p=state.plots[index];if(p.building){showToast('Clear the equipment before planting.');return}if(state.seeds[crop]>0)state.seeds[crop]--;else if(state.money>=3)state.money-=3;else{showToast('You need ◈3 for a seed.');return}p.crop=crop;p.planted=Date.now();p.resilience=(p.resilience*37+crop*19+state.harvested*13)%100;showToast(`${cropData[crop].name} tucked into the soil.`);render()}
function fertilize(index){let p=state.plots[index];if(state.money<12){showToast('You need ◈12 for fertilizer.');return}if(p.building){showToast('There is equipment in the way.');return}state.money-=12;p.fert={seed:(index*73+state.coal*11+23)%100,soil:1+((index*7+state.coal)%4)};p.planted=Date.now();if(p.crop==null)showToast('Fertilizer set. Plant a seed when ready.');else showToast('Fresh fertilizer reset the crop’s growth.');render()}
function trashFor(p,index){if(!p.trashName){let hash=(p.fert?.seed??(index*17+state.coal*3))%crops.length;p.trashName=['Moss scraps','Spore clump','Soft mulch','Dusty husk','Glow compost'][hash%5];p.soilValue=1+(p.fert?.soil||((index+state.coal)%3))}return p.trashName}
function makeTrash(index){let p=state.plots[index];let n=trashFor(p,index);setItem(n,1);state.itemTimes[n]=Date.now();showToast(`${n} gathered. Soil value ${p.soilValue||1}.`);render()}
function harvest(index){let p=state.plots[index];if(!getReady(p))return;let source=cropData[p.crop],chance=p.fert?Math.min(.72,.18+(p.fert.soil||1)*.08):0,mutated=Math.random()<chance;let result=mutated?cropData[Math.floor(Math.random()*cropData.length)]:source;let resilience=typeof p.resilience==='number'?p.resilience:50;let quality=resilience>82?'★★★':resilience>49?'★★':'★';let qty=1+(p.fert?1:0)+(resilience>92?1:0);let itemName=`${result.name} ${quality}`;setItem(itemName,qty);state.itemTimes[itemName]=Date.now();state.harvested+=qty;if(p.fert){setItem(trashFor(p,index),1);showToast(mutated?`Surprise! ${source.name} became ${result.name} ${quality}.`:`${qty} ${result.name} ${quality} gathered · plot trash left behind.`)}else showToast(`${qty} ${result.name} ${quality} gathered.`);p.crop=null;p.planted=0;p.fert=null;p.resilience=(resilience+31+(p.soilValue||0)*2)%100;render()}
function placeBuilding(index){let p=state.plots[index],type=state.buildMode;if(p.crop!=null||p.building){showToast('Choose a quiet, empty plot for equipment.');return}let cost={belt:8,store:30,applicator:40}[type];if(state.money<cost){showToast(`You need ◈${cost}.`);return}state.money-=cost;p.building=type;p.store=0;state.buildMode=null;document.getElementById('modeLabel').textContent='TAP A PLOT TO TEND';showToast(`${type==='store'?'Latch store':type==='belt'?'Belt':'Applicator'} placed.`);render()}
function renderBuild(){let choices=[['belt','↗','Belt',8],['store','▣','Latch store',30],['applicator','◉','Applicator',40]];document.getElementById('buildGrid').innerHTML=choices.map(([id,icon,label,cost])=>`<button class="build-btn ${state.buildMode===id?'active':''}" data-build="${id}"><span>${icon}</span><div>${label}<small>◈ ${cost}</small></div></button>`).join('');document.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>{state.buildMode=state.buildMode===b.dataset.build?null:b.dataset.build;document.getElementById('modeLabel').textContent=state.buildMode?'PLACE '+state.buildMode.toUpperCase():'TAP A PLOT TO TEND';showToast(state.buildMode?'Tap an empty plot to place it.':'Build mode closed.');render()})}
function openMarket(){let modal=document.getElementById('modal'),back=document.getElementById('modalBack');modal.innerHTML=`<button class="modal-close" id="closeModal">×</button><div class="eyebrow">SECTOR 01 · NEIGHBORHOOD EXCHANGE</div><h3>Little market</h3><p>Prices gently wander each day. Buy a seed or sell whatever you have gathered. No rush.</p><div class="market-modal-list">${cropData.slice(0,12).map((c,i)=>`<div class="market-modal-row"><span style="font-size:20px">${c.emoji}</span><div><strong>${c.name}</strong><small>Seed ◈3 · Harvest ◈${c.value} · ${c.grow}s</small></div><button data-buyseed="${i}">BUY SEED</button></div>`).join('')}</div><p class="hint">40 crop varieties in your field notes. Prices are a cozy local-market simulation.</p>`;back.classList.add('show');modal.querySelector('#closeModal').onclick=()=>back.classList.remove('show');modal.querySelectorAll('[data-buyseed]').forEach(b=>b.onclick=()=>{if(state.money<3){showToast('You need ◈3 for a seed.');return}state.money-=3;let i=Number(b.dataset.buyseed);state.seeds[i]=(state.seeds[i]||0)+1;showToast(`${cropData[i].name} seed tucked into your pocket.`);render()})}
function connectedStore(index){return state.plots.some((p,i)=>p.building==='store'&&Math.abs(Math.floor(i/4)-Math.floor(index/4))+Math.abs(i%4-index%4)===1&&state.plots.some((b,j)=>b.building==='belt'&&Math.abs(Math.floor(j/4)-Math.floor(i/4))+Math.abs(j%4-i%4)===1)))}
function stageToStore(index){let p=state.plots[index];if(!connectedStore(index)){showToast('Connect this latch store to a belt first.');return}if(p.unloading){showToast('The full latch is unloading and will not accept items yet.');return}let n=Object.keys(state.items)[0];if(!n){showToast('Your pockets are empty.');return}let amount=Math.min(state.items[n],8-(p.store||0));if(amount<=0){p.unloading=Date.now();showToast('Full latch is unloading automatically.');render();return}setItem(n,-amount);p.store=(p.store||0)+amount;p.storeName=n;if(p.store>=8)p.unloading=Date.now();showToast(`${amount} ${n} staged safely.`);render()}
function tick(){let now=Date.now();let delta=now-(state.lastTick||now);state.lastTick=now;let start=state.startedAt||(state.startedAt=now);state.day=Math.max(1,Math.floor((now-start)/86400000)+1);for(const p of state.plots){if(p.building==='store'&&p.unloading&&now-p.unloading>5000){let amt=p.store||0;if(amt){setItem(p.storeName||'Harvest',amt);state.itemTimes[p.storeName||'Harvest']=now}p.store=0;p.unloading=0;p.storeName=null;showToast('Latch store finished unloading.') }}
 for(const name of Object.keys(state.items)){let time=state.itemTimes[name]||now;if(now-time>90000){let qty=state.items[name];delete state.items[name];delete state.itemTimes[name];if(name.startsWith('Orbit grape')){setItem('Wine',qty);state.itemTimes.Wine=now;showToast('Forgotten Orbit grapes mellowed into wine.')}else{setItem('Waste',qty);state.itemTimes.Waste=now}}}
 if(state.animals.hen>0&&now-(state.lastEgg||start)>95000){setItem('Egg',state.animals.hen);state.itemTimes.Egg=now;state.lastEgg=now}if(state.animals.cow>0&&now-(state.lastMilk||start)>120000){setItem('Full-fat milk',state.animals.cow);state.itemTimes['Full-fat milk']=now;state.lastMilk=now}render()}
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{state.tab=t.dataset.tab;renderTab()});document.getElementById('marketOpen').onclick=openMarket;document.getElementById('allPrices').onclick=openMarket;document.getElementById('newOrder').onclick=()=>{state.order=null;ensureOrder();render();showToast('A fresh neighbor request arrived.')};document.getElementById('modalBack').onclick=e=>{if(e.target.id==='modalBack')e.currentTarget.classList.remove('show')};document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('modalBack').classList.remove('show');if(e.key.startsWith('Arrow')){e.preventDefault();let i=state.selected;state.selected=e.key==='ArrowRight'?Math.min(state.plots.length-1,i+1):e.key==='ArrowLeft'?Math.max(0,i-1):e.key==='ArrowDown'?Math.min(state.plots.length-1,i+4):Math.max(0,i-4);render()}if(e.key==='Enter'){let p=state.plots[state.selected];if(p?.crop!=null&&getReady(p))harvest(state.selected)}});
render();setInterval(tick,1000);
</script></body></html>
