const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
  const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
  const page=await browser.newPage({viewport:{width:1440,height:1000}});
  const errors=[];page.on('pageerror',e=>errors.push(String(e)));
  await page.goto('file:///home/runner/work/PlayGround/PlayGround/index.html');
  await page.evaluate(()=>{let s=JSON.parse(localStorage.getItem('littleOrbitSave'));s.plots[0].planted=Date.now()-50000;localStorage.setItem('littleOrbitSave',JSON.stringify(s));location.reload()});
  await page.waitForTimeout(500);
  await page.locator('#farmGrid .plot').nth(0).click();
  await page.locator('#harvestBtn').click();
  const harvested=await page.locator('#harvestCount').innerText();
  await page.locator('#marketOpen').click();
  await page.locator('[data-buyseed="2"]').click();
  const bought=await page.locator('#wallet').innerText();
  await page.locator('#closeModal').click();
  await page.locator('#farmGrid .plot').nth(3).click();
  await page.locator('#plantBtn').click();
  const planted=await page.locator('#farmGrid .plot').nth(3).innerText();
  console.log(JSON.stringify({harvested,bought,planted,errorCount:errors.length,errors}));
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

